-- ---------------------------------------------------------------------------
-- Default grants
-- ---------------------------------------------------------------------------
-- System Administrator: every permission, unconditionally.
INSERT INTO ATS_ROLE_PERMISSIONS (ROLE_ID, PERMISSION_ID, CONDITION_CODE)
SELECT r.ID, p.ID, 'ALWAYS' FROM ATS_ROLES r CROSS JOIN ATS_PERMISSIONS p WHERE r.CODE = 'SYS_ADMIN';

-- Unconditional grants for the other roles.
INSERT INTO ATS_ROLE_PERMISSIONS (ROLE_ID, PERMISSION_ID, CONDITION_CODE)
SELECT r.ID, p.ID, 'ALWAYS' FROM ATS_ROLES r, ATS_PERMISSIONS p
WHERE (r.CODE, p.CODE) IN (
  ('APP_SUPPORT', 'TICKET_VIEW'), ('APP_SUPPORT', 'TICKET_CREATE'), ('APP_SUPPORT', 'COMMENT_ADD'),
  ('APP_SUPPORT', 'ATTACH_UPLOAD'), ('APP_SUPPORT', 'DASHBOARD_VIEW'),

  ('APP_MANAGER', 'TICKET_VIEW'), ('APP_MANAGER', 'TICKET_CREATE'), ('APP_MANAGER', 'TICKET_EDIT'),
  ('APP_MANAGER', 'TICKET_CHANGE_PRIORITY'), ('APP_MANAGER', 'TICKET_BLOCK'), ('APP_MANAGER', 'TICKET_UNBLOCK'),
  ('APP_MANAGER', 'TICKET_CLOSE'), ('APP_MANAGER', 'TICKET_CANCEL'),
  ('APP_MANAGER', 'ASSIGN_TICKET'), ('APP_MANAGER', 'ASSIGN_REVIEWER'), ('APP_MANAGER', 'ASSIGN_TESTER'),
  ('APP_MANAGER', 'COLLAB_ADD'), ('APP_MANAGER', 'COLLAB_REMOVE'),
  ('APP_MANAGER', 'DEPLOY_MARK_READY'), ('APP_MANAGER', 'VERIFY_RECORD_RESULT'), ('APP_MANAGER', 'VERIFY_CREATE_RELATED'),
  ('APP_MANAGER', 'COMMENT_ADD'), ('APP_MANAGER', 'ATTACH_UPLOAD'), ('APP_MANAGER', 'DASHBOARD_VIEW'), ('APP_MANAGER', 'USER_VIEW'),

  ('DEVELOPER', 'TICKET_VIEW'), ('DEVELOPER', 'COMMENT_ADD'), ('DEVELOPER', 'ATTACH_UPLOAD'), ('DEVELOPER', 'DASHBOARD_VIEW'),

  ('TESTER', 'TICKET_VIEW'), ('TESTER', 'TICKET_CREATE'), ('TESTER', 'COMMENT_ADD'), ('TESTER', 'ATTACH_UPLOAD'), ('TESTER', 'DASHBOARD_VIEW'),

  ('INTEGRATION', 'TICKET_VIEW'), ('INTEGRATION', 'TICKET_CREATE'), ('INTEGRATION', 'DEPLOY_MARK_DEPLOYED'),
  ('INTEGRATION', 'DEPLOY_MARK_READY'), ('INTEGRATION', 'COMMENT_ADD'), ('INTEGRATION', 'ATTACH_UPLOAD'), ('INTEGRATION', 'DASHBOARD_VIEW')
);

-- Conditional grants.
INSERT INTO ATS_ROLE_PERMISSIONS (ROLE_ID, PERMISSION_ID, CONDITION_CODE)
SELECT r.ID, p.ID, c.COND FROM ATS_ROLES r, ATS_PERMISSIONS p,
  (SELECT 'APP_SUPPORT' ROLE_CODE, 'TICKET_EDIT' PERM_CODE, 'TICKET_CREATOR' COND FROM DUAL UNION ALL
   SELECT 'APP_SUPPORT', 'TICKET_CANCEL', 'TICKET_CREATOR' FROM DUAL UNION ALL
   SELECT 'APP_SUPPORT', 'COLLAB_ADD', 'TICKET_CREATOR' FROM DUAL UNION ALL
   SELECT 'APP_SUPPORT', 'VERIFY_RECORD_RESULT', 'TICKET_CREATOR' FROM DUAL UNION ALL
   SELECT 'APP_SUPPORT', 'VERIFY_CREATE_RELATED', 'TICKET_CREATOR' FROM DUAL UNION ALL

   SELECT 'DEVELOPER', 'TICKET_EDIT', 'CURRENT_ASSIGNEE' FROM DUAL UNION ALL
   SELECT 'DEVELOPER', 'TICKET_START_WORK', 'CURRENT_ASSIGNEE' FROM DUAL UNION ALL
   SELECT 'DEVELOPER', 'TICKET_BLOCK', 'CURRENT_ASSIGNEE' FROM DUAL UNION ALL
   SELECT 'DEVELOPER', 'TICKET_UNBLOCK', 'CURRENT_ASSIGNEE' FROM DUAL UNION ALL
   SELECT 'DEVELOPER', 'ASSIGN_REVIEWER', 'CURRENT_ASSIGNEE' FROM DUAL UNION ALL
   SELECT 'DEVELOPER', 'COLLAB_ADD', 'CURRENT_ASSIGNEE' FROM DUAL UNION ALL
   SELECT 'DEVELOPER', 'CODE_CONTRIBUTOR_MANAGE', 'CURRENT_ASSIGNEE' FROM DUAL UNION ALL
   SELECT 'DEVELOPER', 'CODE_CONTRIBUTOR_MANAGE', 'COLLABORATOR' FROM DUAL UNION ALL
   SELECT 'DEVELOPER', 'REVIEW_SUBMIT', 'CURRENT_ASSIGNEE' FROM DUAL UNION ALL
   SELECT 'DEVELOPER', 'REVIEW_SKIP', 'CURRENT_ASSIGNEE' FROM DUAL UNION ALL
   SELECT 'DEVELOPER', 'REVIEW_DECIDE', 'ASSIGNED_REVIEWER' FROM DUAL UNION ALL
   SELECT 'DEVELOPER', 'DEPLOY_SET_PATCH', 'CURRENT_ASSIGNEE' FROM DUAL UNION ALL

   SELECT 'TESTER', 'TEST_RECORD_RESULT', 'ASSIGNED_TESTER' FROM DUAL UNION ALL
   SELECT 'TESTER', 'TEST_UPLOAD_EVIDENCE', 'ASSIGNED_TESTER' FROM DUAL UNION ALL
   SELECT 'TESTER', 'TICKET_EDIT', 'TICKET_CREATOR' FROM DUAL UNION ALL

   SELECT 'INTEGRATION', 'TICKET_EDIT', 'TICKET_CREATOR' FROM DUAL UNION ALL
   SELECT 'INTEGRATION', 'TICKET_START_WORK', 'CURRENT_ASSIGNEE' FROM DUAL
  ) c
WHERE r.CODE = c.ROLE_CODE AND p.CODE = c.PERM_CODE;

-- Everyone may edit/delete their own comments and attachments.
INSERT INTO ATS_ROLE_PERMISSIONS (ROLE_ID, PERMISSION_ID, CONDITION_CODE)
SELECT r.ID, p.ID, CASE WHEN p.CATEGORY = 'COMMENTS' THEN 'COMMENT_AUTHOR' ELSE 'ATTACHMENT_OWNER' END
FROM ATS_ROLES r, ATS_PERMISSIONS p
WHERE r.CODE <> 'SYS_ADMIN' AND p.CODE IN ('COMMENT_EDIT', 'COMMENT_DELETE', 'ATTACH_DELETE');

